// The mikan panel API as a typed client. The types come from the panel's own OpenAPI
// spec (src/schema.ts, generated by openapi-typescript at build time); the calls go
// through openapi-fetch, the same pair the admin panel's web client is built on.
import createFetchClient, { type Client } from "openapi-fetch";
import type { paths } from "./schema.js";

export type { components, operations, paths } from "./schema.js";

export interface MikanOptions {
  /**
   * The API address of the panel, as its API page shows it, with no path after it:
   * https://<panel>:<port>/<secret path>/api/v1
   */
  baseUrl: string;
  /** An API key from Settings → Security → API: mk_... */
  apiKey: string;
  /** A fetch to use instead of the global one (tests, proxies, a runtime with its own). */
  fetch?: typeof globalThis.fetch;
}

/** The typed client: GET, POST, PUT, PATCH and DELETE by the path of the API. */
export type MikanClient = Client<paths>;

/** A client that sends every request with the API key, as `Authorization: Bearer mk_...`. */
export function createClient({ baseUrl, apiKey, fetch }: MikanOptions): MikanClient {
  if (!baseUrl) throw new Error("@getmikan/sdk: baseUrl is empty, give the panel's API address");
  if (!apiKey) throw new Error("@getmikan/sdk: apiKey is empty, give an API key (mk_...)");
  const client = createFetchClient<paths>({ baseUrl, fetch });
  client.use({
    onRequest({ request }) {
      request.headers.set("Authorization", `Bearer ${apiKey}`);
      return request;
    },
  });
  return client;
}
